/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import {
  MESSAGE_EXCEL_SENSITIVE,
  MESSAGE_EXCEL_COLUMNS,
} from 'app/features/notification/message/model/message-excel-columns';
import { MessageRepository } from 'app/features/notification/message/repository/message-repository.service';
import { take, map } from 'rxjs';
import { Message } from 'app/features/notification/message/model/message.model';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'message-view-export-action',
  standalone: false,
  templateUrl: './message-view-export-action.component.html',
})
export class MessageViewExportActionComponent extends BaseExportAction<Message> {
  protected readonly scope = 'notification/message';
  protected readonly repository = inject(MessageRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ExportDefinition<Message> = {
    name: 'notification.message',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: MESSAGE_EXCEL_COLUMNS,
    sensitive: MESSAGE_EXCEL_SENSITIVE,
    references: {
      tenant: {
        names: (refs) =>
          this.tenantRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
